            return {
                "status": 413,
                "body": {
                    "error": "request body too large",
                    "reason": f"request body too large: {n} bytes exceeds limit of {MAX_BODY_SIZE} bytes",
                    "limit_bytes": MAX_BODY_SIZE,
                },
            }
        return {"status": 200, "body": {"accepted_bytes": n, "status": "buffered"}}

